// Generate affine representatives of balanced sets surviving degree-sum and minimum degree tests.
use std::collections::HashSet;
fn main(){let mut seen=HashSet::new();let(mut pass,mut reps)=(0,0);for code in 0..531441{let mut t=code;let mut w=[0u32;13];for j in 1..13{w[j]=j as u32+13*(t%3);t/=3;}let mut h=[0u32;39];for a in w{for b in w{h[((a+b)%39)as usize]+=1}}if h.iter().any(|x|*x<2)||h.iter().map(|x|(2*x).min(9)).sum::<u32>()<272{continue}pass+=1;let m=w.iter().map(|x|1u64<<x).sum::<u64>();if seen.contains(&m){continue}reps+=1;println!("{m}");for u in 1..39{if u%3==0||u%13==0{continue}for a in w{seen.insert(w.iter().map(|b|1u64<<((u*(39+b-a))%39)).sum::<u64>());}}}eprintln!("after fixing weight at residue zero to zero: passing {pass} / 531441; affine reps {reps}");}
